import typing


class FieldABC:
    """Abstract base class from which all Field classes inherit."""

    parent = None
    name = None

    def serialize(self, attr, obj, accessor=None):
        raise NotImplementedError

    def deserialize(self, value):
        raise NotImplementedError

    def _serialize(self, value, attr, obj, **kwargs):
        raise NotImplementedError

    def _deserialize(self, value, attr, data, **kwargs):
        raise NotImplementedError


class SchemaABC:
    """Abstract base class from which all Schemas inherit."""

    def dump(self, obj, *, many: typing.Optional[bool] = None):
        raise NotImplementedError

    def dumps(self, obj, *, many: typing.Optional[bool] = None):
        raise NotImplementedError

    def load(
        self, data, *, many: typing.Optional[bool] = None, partial=None, unknown=None
    ):
        raise NotImplementedError

    @property
    def context(self):
        """The context dictionary for the parent :class:`Schema`."""
        return self.parent.context

    @property
    def root(self):
        """Reference to the `Schema` that this field belongs to even if it is buried in a
        container field (e.g. `List`).
        Return `None` for unbound fields.
        """
        ret = self
        while hasattr(ret, "parent"):
            ret = ret.parent
        return ret if isinstance(ret, SchemaABC) else None


